const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { param, query, validationResult } = require('express-validator');
const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers (helps protect against XSS, clickjacking, etc.)
app.use(helmet());

// Rate limiting - prevents brute-force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Parse JSON with size limit - prevents large payload attacks
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded bodies with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// INPUT VALIDATION MIDDLEWARE
// ============================================

// Validate and sanitize input - catches validation errors before route handlers
const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Invalid input', 
      details: errors.array() 
    });
  }
  next();
};

// ============================================
// VALIDATION RULES
// ============================================

