const userIdValidation = [
  param('id')
    .trim()
    .escape() // Sanitize HTML characters to prevent XSS
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
    .toInt(),
];

// Validation for paginated /users endpoint
const usersQueryValidation = [
  query('page')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Page must be a positive integer')
    .toInt(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
];

// ============================================
// API ROUTES
// ============================================

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', usersQueryValidation, validateInput, (req, res) => {
  // Extract validated and sanitized parameters
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;

  // In production: fetch from database with pagination
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply pagination
  const startIndex = (page - 1) * limit;
  const endIndex = page * limit;
  const paginatedUsers = users.slice(startIndex, endIndex);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: users.length,
    },
  });
});

app.get('/users/:id', userIdValidation, validateInput, (req, res) => {
  const userId = parseInt(req.params.id);

  // In production: fetch from database with parameterized queries
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  res.json(user);
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler for unmatched routes
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found' });
});

// Global error handler - prevents stack trace exposure in production
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error('Error:', err.message); // Log internally

  // Different messages for development vs production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({ error: message });
});

// ============================================
// SERVER STARTUP
// ============================================

