// Secure Express.js application with proper error handling and input validation

const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS control

const app = express();

// === SECURITY MIDDLEWARE ===

// Set security-related HTTP headers
app.use(helmet());

// Enable CORS with configurable options
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'https://trusted-domain.com',
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Rate limiting to prevent brute-force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Parse JSON with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));

// === INPUT VALIDATION ===

// Simple validation helper
const validateQueryParams = (allowedParams) => (req, res, next) => {
  const invalidParams = Object.keys(req.query).filter(
    key => !allowedParams.includes(key)
  );

  if (invalidParams.length > 0) {
    return res.status(400).json({ 
      error: 'Invalid query parameters',
      invalidParams 
    });
  }
  next();
};

// === ROUTES ===

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Sanitize user data - remove sensitive fields if needed
const sanitizeUser = (user) => {
  const { ...safeUser } = user;
  // Optionally remove email if not needed:
  // delete safeUser.email;
  return safeUser;
};

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/users', validateQueryParams(['page', 'limit']), (req, res) => {
  try {
    // Validate and sanitize numeric query params
    const page = Math.max(1, parseInt(req.query.page) || 1);
    const limit = Math.min(100, Math.max(1, parseInt(req.query.limit) || 10));
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;

    const paginatedUsers = users
      .slice(startIndex, endIndex)
      .map(sanitizeUser); // Sanitize before sending

    res.json({
      data: paginatedUsers,
      pagination: { page, limit, total: users.length }
    });
  } catch (error) {
    // Log the actual error internally (don't expose to client)
    console.error('Error fetching users:', error.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// === ERROR HANDLING MIDDLEWARE ===

// 404 handler for unknown routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err.message);

  // Don't leak stack traces in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(err.status || 500).json({ error: message });
});

// === SERVER START ===

